void Load(int index,bool auto,bool backup=false){try{var loaded=SaveStore.Load(index,auto,backup);loaded.settings=SettingsStore.Load(c,loaded.settings);s=loaded;g=new GameService(c,s);g.SetSailingMode("normal");g.Workflow.RestoreOffline(DateTime.UtcNow);page=s.ended&&s.screen=="结局"?"结局":s.atSea?"航海":"城市";paused=false;selectedPort=(s.city+1)%c.ports.Length;SaveStore.Save(s,true);Notify("档案恢复完成；离线进度已按离线档位结算");}catch(Exception e){Notify("读取失败，原档保留："+e.Message);}}
